fn putmask(a: Vec<f32>, mask: Vec<bool>, values: Vec<f32>) -> Vec<f32> {
    let len = a.len();
    // We'll create a result vector with capacity len.
    // For each index i, if mask[i] is true, pick from values with wrapping index,
    // else keep a[i].
    let values_len = values.len();

    // Since mask and a have the same length as per problem statement,
    // no bounds checks needed other than these assumptions.
    let mut result = Vec::with_capacity(len);
    for i in 0..len {
        if mask[i] {
            // replacement index with wrap-around
            let replacement = values[i % values_len];
            result.push(replacement);
        } else {
            result.push(a[i]);
        }
    }
    result
}